LOCAL_MACROS = (
    ((18, 18), (30, 18)),
    ((24, 18), (36, 18)),
    ((30, 18), (42, 18)),
    ((36, 18), (48, 18)),
    ((48, 12), (48, 24)),
    ((54, 24), (42, 24)),
    ((42, 18), (42, 30)),
    ((42, 24), (42, 36)),
    ((42, 30), (42, 42)),
